def parse_filename(filename):
    import re
    from datetime import datetime

    match = re.fullmatch(r"([^_]+)_(\d{8})_(\d{4})\.wav", filename)
    if not match:
        raise ValueError(f"Invalid filename format: {filename!r}")

    site, date_str, time_str = match.groups()
    try:
        dt = datetime.strptime(date_str + time_str, "%Y%m%d%H%M")
    except ValueError as exc:
        raise ValueError(f"Invalid date or time in filename: {filename!r}") from exc

    return site, dt.date(), dt.time()
